public struct FfiConverterTypeFieldKitCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = FieldKitCore

    public static func lift(_ handle: UInt64) throws -> FieldKitCore {
        return FieldKitCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: FieldKitCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FieldKitCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: FieldKitCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


