/**
 * Everything that can go wrong, in the app's words. `fieldkit_error_kind`
 * maps each case to the framework's [`ErrorKind`].
 */
public 
enum FieldKitError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case EmptyTitle
    case TitleTooLong(max: UInt32
    )
    case EmptyNote
    case NoteTooLong(max: UInt32
    )
    case NotFound(id: Int64
    )
    case AlreadyRecording
    case NotRecording
    case File(reason: String
    )
    case InUse
    case Corrupt(reason: String
    )
    case NewerData
    case Storage(reason: String
    )
    /**
     * Stopped by the runtime: cancelled, interrupted by the background,
     * or shut down. `kind` says which.
     */
    case Stopped(kind: ErrorKind
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FieldKitError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFieldKitError: FfiConverterRustBuffer {
    typealias SwiftType = FieldKitError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FieldKitError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .EmptyTitle
        case 2: return .TitleTooLong(
            max: try FfiConverterUInt32.read(from: &buf)
            )
        case 3: return .EmptyNote
        case 4: return .NoteTooLong(
            max: try FfiConverterUInt32.read(from: &buf)
            )
        case 5: return .NotFound(
            id: try FfiConverterInt64.read(from: &buf)
            )
        case 6: return .AlreadyRecording
        case 7: return .NotRecording
        case 8: return .File(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .InUse
        case 10: return .Corrupt(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 11: return .NewerData
        case 12: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 13: return .Stopped(
            kind: try FfiConverterTypeErrorKind.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FieldKitError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .EmptyTitle:
            writeInt(&buf, Int32(1))
        
        
        case let .TitleTooLong(max):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(max, into: &buf)
            
        
        case .EmptyNote:
            writeInt(&buf, Int32(3))
        
        
        case let .NoteTooLong(max):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(max, into: &buf)
            
        
        case let .NotFound(id):
            writeInt(&buf, Int32(5))
            FfiConverterInt64.write(id, into: &buf)
            
        
        case .AlreadyRecording:
            writeInt(&buf, Int32(6))
        
        
        case .NotRecording:
            writeInt(&buf, Int32(7))
        
        
        case let .File(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InUse:
            writeInt(&buf, Int32(9))
        
        
        case let .Corrupt(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NewerData:
            writeInt(&buf, Int32(11))
        
        
        case let .Storage(reason):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Stopped(kind):
            writeInt(&buf, Int32(13))
            FfiConverterTypeErrorKind.write(kind, into: &buf)
            
        }
    }
}


